#include <torch/extension.h>
#include <ATen/cuda/CUDAContext.h>
#include "kernel.h"
#include <string>

static void check_bf16_contiguous_cuda(
    const torch::Tensor& tensor, const std::string& name) {
    TORCH_CHECK(tensor.is_cuda(), name, " must be a CUDA tensor");
    TORCH_CHECK(
        tensor.dtype() == torch::kBFloat16,
        name, " must have bfloat16 dtype, got ", tensor.dtype());
    TORCH_CHECK(tensor.is_contiguous(), name, " must be contiguous");
}

static void check_fp32_contiguous_cuda(
    const torch::Tensor& tensor, const std::string& name) {
    TORCH_CHECK(tensor.is_cuda(), name, " must be a CUDA tensor");
    TORCH_CHECK(
        tensor.dtype() == torch::kFloat32,
        name, " must have float32 dtype, got ", tensor.dtype());
    TORCH_CHECK(tensor.is_contiguous(), name, " must be contiguous");
}

// Destination-passing-style entry. Per definition.json:
//   grad_cos        : [batch_size, seq_len, head_dim] bf16
//   grad_sin        : [batch_size, seq_len, head_dim] bf16
//   idx_theta       : [batch_size, seq_len, head_dim] fp32
//   grad_idx_theta  : [batch_size, seq_len, head_dim] fp32 (DPS)
//
// batch_size, seq_len, and head_dim are all workload-variable
// (no pinned constants for this slug).
void run(
    const torch::Tensor& grad_cos,
    const torch::Tensor& grad_sin,
    const torch::Tensor& idx_theta,
    torch::Tensor grad_idx_theta
) {
    TORCH_CHECK(grad_cos.dim() == 3,
                "grad_cos must be 3D [B, S, D]");
    TORCH_CHECK(grad_sin.dim() == 3,
                "grad_sin must be 3D [B, S, D]");
    TORCH_CHECK(idx_theta.dim() == 3,
                "idx_theta must be 3D [B, S, D]");
    TORCH_CHECK(grad_idx_theta.dim() == 3,
                "grad_idx_theta must be 3D [B, S, D]");
    TORCH_CHECK(grad_cos.sizes() == idx_theta.sizes(),
                "grad_cos shape must match idx_theta");
    TORCH_CHECK(grad_sin.sizes() == idx_theta.sizes(),
                "grad_sin shape must match idx_theta");
    TORCH_CHECK(grad_idx_theta.sizes() == idx_theta.sizes(),
                "grad_idx_theta shape must match idx_theta");

    check_bf16_contiguous_cuda(grad_cos, "grad_cos");
    check_bf16_contiguous_cuda(grad_sin, "grad_sin");
    check_fp32_contiguous_cuda(idx_theta, "idx_theta");
    check_fp32_contiguous_cuda(grad_idx_theta, "grad_idx_theta");

    cudaStream_t stream = at::cuda::getCurrentCUDAStream();
    problem_090_batched_2d_rope_backward_launcher(
        grad_cos, grad_sin, idx_theta, grad_idx_theta, stream);
}

PYBIND11_MODULE(TORCH_EXTENSION_NAME, m) {
    m.def(
        "run", &run,
        "BF16/fp32 batched 2D RoPE position-encoding backward: "
        "computes grad_idx_theta = -grad_cos.f32 * sin(idx_theta) "
        "+ grad_sin.f32 * cos(idx_theta) per element. No reductions.");
}

#include "kernel.h"
#include <cuda_bf16.h>
#include <cuda_runtime.h>

// BF16/fp32 batched 2D RoPE position-encoding backward.
//
// Per-element compute (no reductions, no broadcasts):
//   grad_idx_theta[b, s, d] = -grad_cos[b, s, d].f32 * sin(idx_theta[b, s, d])
//                            + grad_sin[b, s, d].f32 * cos(idx_theta[b, s, d])
//
// Each thread does:
//   * load fp32 idx_theta,
//   * SFU sinf + cosf,
//   * load BF16 grad_cos and grad_sin, cast to fp32,
//   * fused multiply-add to produce the fp32 output,
//   * store fp32 grad_idx_theta.
//
// One CTA per (b, s) row. Grid: (seq_len, batch_size).
// BLOCK_THREADS = 256; each thread stride-loops over head_dim.

namespace {

constexpr int kBlockThreads = 256;

__global__ void __launch_bounds__(kBlockThreads, 4)
problem_090_grad_idx_theta_kernel(
    const __nv_bfloat16* __restrict__ grad_cos,
    const __nv_bfloat16* __restrict__ grad_sin,
    const float* __restrict__ idx_theta,
    float* __restrict__ grad_idx_theta,
    int head_dim) {

    const int s = blockIdx.x;
    const int b = blockIdx.y;
    const int seq_len = gridDim.x;
    const int row_offset =
        (b * seq_len + s) * head_dim;

    const int tid = threadIdx.x;
    for (int d = tid; d < head_dim; d += kBlockThreads) {
        const int idx = row_offset + d;

        const float idx_t = idx_theta[idx];
        const float sin_t = sinf(idx_t);
        const float cos_t = cosf(idx_t);

        const float g_cos = __bfloat162float(grad_cos[idx]);
        const float g_sin = __bfloat162float(grad_sin[idx]);

        grad_idx_theta[idx] = -g_cos * sin_t + g_sin * cos_t;
    }
}

}  // namespace

void problem_090_batched_2d_rope_backward_launcher(
    const torch::Tensor& grad_cos,
    const torch::Tensor& grad_sin,
    const torch::Tensor& idx_theta,
    torch::Tensor& grad_idx_theta,
    cudaStream_t stream) {

    const int batch_size = static_cast<int>(idx_theta.size(0));
    const int seq_len = static_cast<int>(idx_theta.size(1));
    const int head_dim = static_cast<int>(idx_theta.size(2));

    dim3 grid(seq_len, batch_size);
    dim3 block(kBlockThreads);

    problem_090_grad_idx_theta_kernel<<<grid, block, 0, stream>>>(
        reinterpret_cast<const __nv_bfloat16*>(
            grad_cos.data_ptr<at::BFloat16>()),
        reinterpret_cast<const __nv_bfloat16*>(
            grad_sin.data_ptr<at::BFloat16>()),
        idx_theta.data_ptr<float>(),
        grad_idx_theta.data_ptr<float>(),
        head_dim);
}

#pragma once

#ifndef PROBLEM_090_BATCHED_2D_ROPE_POSITION_ENCODING_BACKWARD_KERNEL_H
#define PROBLEM_090_BATCHED_2D_ROPE_POSITION_ENCODING_BACKWARD_KERNEL_H

#include <cuda_runtime.h>
#include <torch/extension.h>

// Host launcher for the BF16/fp32 batched 2D RoPE position encoding
// backward kernel. The reference forward emits cos(idx_theta) and
// sin(idx_theta); the backward computes:
//   grad_idx_theta = -grad_cos.f32 * sin(idx_theta)
//                  +  grad_sin.f32 * cos(idx_theta)
//
// Pure per-element kernel: no reductions, no broadcasts, no
// head-axis collapse. Every output element depends on exactly the
// three input elements at the same position.
//
// One CTA per (b, s) row over head_dim elements; BLOCK_THREADS =
// 256 (each thread stride-loops over the row). batch_size, seq_len,
// and head_dim are all workload-variable.
void problem_090_batched_2d_rope_backward_launcher(
    const torch::Tensor& grad_cos,
    const torch::Tensor& grad_sin,
    const torch::Tensor& idx_theta,
    torch::Tensor& grad_idx_theta,
    cudaStream_t stream);

#endif  // PROBLEM_090_BATCHED_2D_ROPE_POSITION_ENCODING_BACKWARD_KERNEL_H
